es_updated_at,update_jornada_parametros_updated_at,update_landing_leads_updated_at,update_landing_vagas_updated_at,update_manuais_gerados_updated_at,update_marketplace_contratacoes_updated_at,update_marketplace_denuncias_updated_at,update_marketplace_leads_updated_at,update_marketplace_pacotes_updated_at,update_marketplace_profissionais_updated_at,update_marketplace_servicos_updated_at,update_meta_acoes_updated_at,update_meta_aem_updated_at,update_meta_okrs_updated_at,update_metas_updated_at,update_ocorrencias_updated_at,update_onboarding_etapas_updated_at,update_onboarding_processos_updated_at,update_onboarding_templates_updated_at,update_ouvidoria_roteamento_updated_at,update_ouvidoria_updated_at,update_participacoes_updated_at,update_pdi_acoes_updated_at,update_pdi_assinatura_links_updated_at,update_pdi_metas_updated_at,update_pdis_updated_at,update_perfis_acesso_updated_at,update_plano_acoes_updated_at,update_plano_comentarios_updated_at,update_plano_tarefas_updated_at,update_plano_templates_updated_at,update_ponto_banco_horas_updated_at,update_ponto_cct_config_updated_at,update_ponto_configuracao_updated_at,update_ponto_diario_updated_at,update_ponto_escalas_updated_at,update_ponto_espelhos_updated_at,update_ponto_fechamentos_updated_at,update_ponto_links_updated_at,update_ponto_repc_importacoes_updated_at,update_profiles_updated_at,update_programa_validador_clientes_updated_at,update_programa_validador_contratos_updated_at,update_programa_validador_documentos_updated_at,update_psico_resp_tecnico_updated_at,update_psicossocial_campanhas_updated_at,update_psicossocial_convites_updated_at,update_sst_dados_extraidos_updated_at,update_sst_documentos_updated_at,update_sst_exposicao_agentes_updated_at,update_superadmins_updated_at,update_suporte_tickets_updated_at,update_tenants_updated_at,update_terceiro_documentos_updated_at,update_terceiro_trabalhadores_updated_at,update_terceiro_treinamentos_updated_at,update_terceiros_updated_at,update_trilha_modulos_updated_at,update_trilha_progresso_updated_at,update_trilha_terceiro_progresso_updated_at,update_trilhas_updated_at,update_usuario_perfil_vinculos_updated_at,usuario_vinculos_updated_at,usuarios_base_updated_at,valida_cpf_admissao,valida_cpf_usuario,valida_desligamento_afastamento,valida_hierarquia_empresa,versiona_documento', ',')) AS nome),
mig_views AS MATERIALIZED (SELECT unnest(string_to_array('admissoes_segura,beneficios_colaboradores_segura,ferias_alertas_segura,ferias_relatorio_setor,marketplace_profissionais_publico,psicossocial_participacao_stats,public,qa_cobertura,so,with', ',')) AS nome),
mig_crons AS MATERIALIZED (SELECT unnest(string_to_array('decimo_terceiro_alertas_diario', ',')) AS nome),
prod_tabelas AS MATERIALIZED (
  SELECT c.relname::text AS nome, c.relrowsecurity AS rls
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind IN ('r','p')
    AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid = c.oid AND d.deptype = 'e')
),
prod_funcoes AS MATERIALIZED (
  SELECT DISTINCT p.proname::text AS nome
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
    AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid = p.oid AND d.deptype = 'e')
),
prod_triggers AS MATERIALIZED (
  SELECT DISTINCT t.tgname::text AS nome, c.relname::text AS tabela
  FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND NOT t.tgisinternal
),
prod_views AS MATERIALIZED (
  SELECT c.relname::text AS nome
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind IN ('v','m')
    AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid = c.oid AND d.deptype = 'e')
),
prod_crons AS MATERIALIZED (
  SELECT jobname::text AS nome,
         left(regexp_replace(command, 'eyJ[A-Za-z0-9_.-]+', '<jwt-oculto>', 'g'), 160) AS detalhe
  FROM cron.job
),
resultado AS (
  SELECT 'so_producao' AS situacao, 'tabela' AS tipo, p.nome,
         CASE WHEN p.rls THEN 'RLS ligada' ELSE 'SEM RLS' END AS detalhe
    FROM prod_tabelas p WHERE p.nome NOT IN (SELECT nome FROM mig_tabelas)
  UNION ALL
  SELECT 'so_producao', 'funcao', p.nome, NULL
    FROM prod_funcoes p WHERE p.nome NOT IN (SELECT nome FROM mig_funcoes)
  UNION ALL
  SELECT 'so_producao', 'trigger', p.nome, 'em ' || p.tabela
    FROM prod_triggers p WHERE p.nome NOT IN (SELECT nome FROM mig_triggers)
  UNION ALL
  SELECT 'so_producao', 'view', p.nome, NULL
    FROM prod_views p WHERE p.nome NOT IN (SELECT nome FROM mig_views)
  UNION ALL
  SELECT 'so_producao', 'cron', p.nome, p.detalhe
    FROM prod_crons p WHERE p.nome NOT IN (SELECT nome FROM mig_crons)
  UNION ALL
  SELECT 'sem_rls_em_producao', 'tabela', p.nome, 'RLS desligada (inclui tabelas que ja estao nas migrations)'
    FROM prod_tabelas p WHERE NOT p.rls AND p.nome IN (SELECT nome FROM mig_tabelas)
  UNION ALL
  SELECT 'so_migration', 'tabela', m.nome, 'nas migrations, ausente em producao'
    FROM mig_tabelas m, param WHERE param.mostrar_faltantes AND m.nome NOT IN (SELECT nome FROM prod_tabelas)
  UNION ALL
  SELECT 'so_migration', 'funcao', m.nome, 'nas migrations, ausente em producao'
    FROM mig_funcoes m, param WHERE param.mostrar_faltantes AND m.nome NOT IN (SELECT nome FROM prod_funcoes)
  UNION ALL
  SELECT 'so_migration', 'cron', m.nome, 'nas migrations, ausente em producao'
    FROM mig_crons m, param WHERE param.mostrar_faltantes AND m.nome NOT IN (SELECT nome FROM prod_crons)
)
SELECT situacao, tipo, nome, detalhe,
       (SELECT count(*) FROM resultado) AS total_linhas
FROM resultado
ORDER BY situacao DESC, tipo, nome;
